    ("mn/license", "CE", 3, "The Commissioner must publicise each licence year's module outline no later than:", "April 1", ["January 1", "June 15", "December 31"], "82.61(h)"),
    ("mn/license", "CE", 3, "A broker may host approved continuing education on company premises if:", "The course is open to any interested individual, with access restricted only by class size", ["Only the company's licensees attend", "The Commissioner approves each session"], "82.61(e)"),
    ("mn/license", "CE", 3, "Prelicense instruction courses may NOT be offered by:", "A person or company licensed to engage in the real estate business", ["A college or university", "A private real estate school"], "82.61(e)"),
    ("mn/license", "CE", 2, "A licensee who claims credit for continuing education not actually completed:", "Has violated 82.61", ["Is simply denied the credit", "May be audited but not disciplined"], "82.61(a)"),
    ("mn/license", "CE", 3, "The agency and fair housing one-hour requirements do not apply to:", "Licensees engaged solely in commercial real estate who file a verification of that status", ["Brokers", "Licensees over 65", "Inactive licensees"], "82.61(c)"),
    ("mn/license", "Renewal", 1, "A Minnesota real estate licence period is:", "24 months, with licences expiring June 30", ["12 months, expiring December 31", "36 months", "24 months, expiring on the issue anniversary"], "82.63 subd. 5"),
    ("mn/license", "Renewal", 2, "Who renews an eligible salesperson's licence in Minnesota?", "The broker", ["The salesperson alone", "The Commissioner automatically"], "82.62 subd. 2(a)"),
    ("mn/license", "Renewal", 2, "A salesperson is an \"eligible salesperson\" for renewal if requirements are met before:", "June 15 of the renewal year", ["June 30", "July 1", "May 1"], "82.62 subd. 2(a)"),
    ("mn/license", "Renewal", 3, "If the broker misses the renewal deadline for an eligible salesperson:", "The broker pays any resulting higher licence fees", ["The salesperson pays a penalty", "The licence is revoked"], "82.62 subd. 2(c)"),
    ("mn/license", "Renewal", 2, "A licensee who has not received notice of renewal approval may not transact business after:", "June 30 of the renewal year", ["July 31", "The licence anniversary", "December 31"], "82.62 subd. 3"),
    ("mn/license", "Renewal", 2, "A Minnesota licensee who fails to renew for two years must:", "Take the examination again", ["Pay a late fee only", "Complete 15 additional hours"], "82.62 subd. 5"),
    ("mn/license", "Renewal", 3, "A salesperson who fails to comply with the continuing education requirement has their licence:", "Cancelled by the Commissioner", ["Suspended for 30 days", "Placed on probation"], "82.62 subd. 1"),
    ("mn/license", "Status", 2, "A Minnesota salesperson may be licensed to:", "Only one broker in this state at a time", ["Two brokers with written consent", "Any number of brokers"], "82.63 subd. 4"),
    ("mn/license", "Status", 2, "When a salesperson terminates activity with a broker, the broker must notify the Commissioner within:", "Ten days", ["Three days", "Thirty days", "Immediately"], "82.63 subd. 6"),
    ("mn/license", "Status", 3, "A salesperson who does not apply to transfer before the licence period ends must:", "File an application for a new licence", ["Pay a reinstatement fee only", "Retake the examination"], "82.63 subd. 6"),
    ("mn/license", "Status", 2, "If a broker's licence is suspended, the salesperson's licence is:", "Not effective during that period", ["Unaffected", "Automatically transferred to another broker"], "82.82 subd. 2"),
    ("mn/license", "Status", 2, "A temporary broker's permit issued on a broker's death lasts:", "45 days, renewable once", ["30 days, not renewable", "90 days", "Six months"], "82.63 subd. 12"),
    ("mn/license", "Status", 3, "An additional broker's licence requires ownership of at least:", "20 percent of each business entity, or officer, signing partner or managing member status in both", ["51 percent", "10 percent", "Any ownership at all"], "82.63 subd. 2"),
    ("mn/license", "Status", 2, "A broker is responsible for:", "The acts of all the broker's salespeople and closing agents acting on the broker's behalf", ["Only employees, not independent contractors", "Only acts the broker approved"], "82.63 subd. 3"),
    ("mn/license", "Status", 3, "The Commissioner may not issue or renew a licence if the applicant owes delinquent state taxes of:", "$500 or more", ["Any amount", "$100 or more", "$5,000 or more"], "82.82 subd. 9(a)"),
    ("mn/license", "Reciprocity", 3, "Minnesota may waive education requirements for an out-of-state licensee if:", "A written reciprocal agreement is in effect, the licensee is in good standing, and that state's requirements are substantially similar", ["The licensee has five years' experience", "The licensee pays a double fee"], "82.64"),
    ("mn/license", "Recovery fund", 1, "The Minnesota recovery fund cap per claimant per transaction is:", "$150,000", ["$50,000", "$100,000", "$250,000"], "82.86 subd. 7"),
    ("mn/license", "Recovery fund", 2, "The aggregate recovery fund cap per licensee is:", "$250,000", ["$150,000", "$500,000", "There is none"], "82.86 subd. 7"),
    ("mn/license", "Recovery fund", 2, "A recovery fund claim must rest on:", "A final judgment for fraudulent, deceptive or dishonest practices or conversion of trust funds", ["A Commissioner's censure", "A sworn written complaint"], "82.86 subd. 7"),
    ("mn/license", "Recovery fund", 3, "Does the judgment debtor's bankruptcy discharge bar a Minnesota recovery fund claim?", "No", ["Yes, always", "Yes, unless the court orders otherwise"], "82.86 subd. 7"),
    ("mn/license", "Recovery fund", 2, "May a licensee recover from the fund for a lost commission?", "No, under no circumstances", ["Yes, up to $150,000", "Yes, if the client acted fraudulently"], "82.86 subd. 7"),
    ("mn/license", "Recovery fund", 3, "Joint tenants making a recovery fund claim are treated as:", "A single claimant", ["Separate claimants each capped at $150,000", "Ineligible claimants"], "82.86 subd. 7"),
    ("mn/license", "Recovery fund", 3, "Payment of an accelerated recovery fund claim results in:", "Automatic suspension of the licensee's licence", ["A written reprimand", "No licensing consequence"], "82.86 subd. 8(c)"),
    ("mn/license", "Recovery fund", 3, "The accelerated claims process may pay no more than:", "$50,000 against one licensee", ["$150,000", "$250,000", "$25,000"], "82.86 subd. 8(f)"),
    ("mn/license", "Recovery fund", 2, "The recovery fund fee is:", "$30 on an initial licence and $20 per licensing period on renewal", ["$50 initial and $50 renewal", "$20 once only", "$100 every renewal"], "82.86 subd. 3"),
    ("mn/license", "Recovery fund", 3, "At the recovery fund hearing the claimant must show they are:", "Not the spouse of the judgment debtor or that spouse's personal representative", ["A Minnesota resident", "Represented by counsel"], "82.86 subd. 9(a)"),
    ("mn/license", "Recovery fund", 3, "Recovery from the fund is unavailable where the buyer's participation was:", "For investment purposes only, limited to providing capital", ["For a second home", "Through a business entity"], "82.86 subd. 7"),

    # conduct
    ("mn/conduct", "Listings", 1, "Before placing a for-sale sign on a property, a Minnesota licensee must have:", "A signed listing agreement or other signed written authorisation", ["An oral authorisation", "An emailed instruction", "An MLS entry"], "82.66 subd. 1(a)"),
    ("mn/conduct", "Listings", 2, "A Minnesota override clause may not exceed:", "Six months after expiration, except two years for a business sale", ["Three months", "One year", "There is no limit"], "82.66 subd. 1(c), (d)(2)"),
    ("mn/conduct", "Listings", 1, "An override clause is unenforceable unless a protective list is furnished within:", "72 hours after the agreement expires", ["10 days", "30 days", "24 hours"], "82.66 subd. 1(d)(1)"),
    ("mn/conduct", "Listings", 2, "Minnesota listing agreements may NOT contain:", "A holdover clause or automatic extension", ["A definite expiration date", "An override clause of six months"], "82.66 subd. 1(c)"),
    ("mn/conduct", "Listings", 3, "Merely mailing property literature to a prospect:", "Is not by itself an affirmative showing of interest for a protective list", ["Places the prospect on the protective list", "Creates a customer relationship"], "82.66 subd. 1(e)"),
    ("mn/conduct", "Listings", 2, "A residential listing must require the seller to state in writing:", "Whether it is acceptable for the licensee to arrange closing services", ["The seller's lowest acceptable price", "The seller's net proceeds goal"], "82.66 subd. 1(b)(10)"),
    ("mn/conduct", "Listings", 2, "A Minnesota listing agreement must include:", "A definite expiration date", ["A guaranteed sale price", "An automatic extension clause"], "82.66 subd. 1(b)(1)"),
    ("mn/conduct", "Listings", 3, "The two-year override clause is available only:", "In conjunction with the purchase or sale of a business", ["For commercial property", "For listings over $1 million"], "82.66 subd. 1(d)(2)"),
    ("mn/conduct", "Listings", 2, "A buyer's broker agreement must be signed:", "Before the licensee performs any acts as the buyer's representative", ["Before writing the first offer", "At closing"], "82.66 subd. 2(a)"),
    ("mn/conduct", "Listings", 3, "For a buyer's broker protective list, the licensee must show each property was:", "Shown to, or specifically brought to the attention of, the buyer during the agreement", ["Listed in the MLS during the agreement", "Within the buyer's price range"], "82.66 subd. 2(e)"),
    ("mn/conduct", "Advertising", 1, "Minnesota advertising must clearly and conspicuously display:", "The real estate brokerage name", ["The licensee's licence number", "The team name", "The listing price"], "82.69(a)"),
    ("mn/conduct", "Advertising", 2, "A team or group name may appear in advertising if:", "The primary broker authorises it and the brokerage name is still clearly and conspicuously displayed", ["The team has at least three members", "It is registered with the Commissioner"], "82.69(b)"),
    ("mn/conduct", "Advertising", 2, "Claiming membership in a real estate organisation the licensee does not belong to is:", "A fraudulent, deceptive or dishonest practice", ["An advertising technicality", "Permitted while an application is pending"], "82.81 subd. 12(a)(7)"),
    ("mn/conduct", "BPO", 2, "A broker may charge a fee for a broker price opinion only if:", "The licence is active and in good standing", ["An appraiser reviews it", "The client is a lender"], "82.735 subd. 1"),
    ("mn/conduct", "BPO", 3, "A broker price opinion may NOT be used as:", "The primary basis of value for originating a residential mortgage on a consumer's principal dwelling", ["A listing price recommendation", "Buyer due diligence", "Lienholder due diligence"], "82.735 subd. 2(4)"),
    ("mn/conduct", "BPO", 2, "A written broker price opinion must include:", "A disclaimer that it is not an appraisal and may not be used in lieu of one", ["An appraiser's certification", "A USPAP compliance statement"], "82.735 subd. 3(a)(9)"),
    ("mn/conduct", "BPO", 3, "A written broker price opinion must disclose:", "Any existing or contemplated interest of the licensee issuing it", ["The licensee's commission rate", "The seller's motivation"], "82.735 subd. 3(a)(5)"),
    ("mn/conduct", "Guaranteed sale", 2, "A guaranteed sale program disclosure must be given to the seller:", "Before the listing agreement is executed", ["When the guarantee is triggered", "Within 72 hours of listing"], "82.74"),
    ("mn/conduct", "Guaranteed sale", 3, "A guaranteed sale program disclosure must set out:", "The general terms and conditions of the purchase and the disposition of any profit on resale", ["The broker's net worth", "The appraised value"], "82.74"),
    ("mn/conduct", "Prohibitions", 2, "A licensee may guarantee future profits only if:", "The guarantee and its assumptions are fully disclosed and contained in the contract or instrument of sale or lease", ["Never, under any circumstances", "The guarantee is given orally"], "82.81 subd. 10"),
    ("mn/conduct", "Negotiations", 1, "Written offers in Minnesota must be:", "Promptly submitted in writing to the seller or lessor", ["Presented only if at or above list price", "Summarised orally to the seller"], "82.71 subd. 1"),
    ("mn/conduct", "Negotiations", 2, "May a licensee tell another prospective buyer the terms of an offer?", "Not before the offer has been presented to the seller", ["Yes, to encourage a higher offer", "Yes, with the seller's oral consent"], "82.71 subd. 2"),
    ("mn/conduct", "Negotiations", 2, "Closing costs must be disclosed to a buyer or seller:", "At or before the time an offer is written or presented", ["At closing", "Within three days of ratification"], "82.71 subd. 3"),
    ("mn/conduct", "Negotiations", 3, "Copies of documents material to the transaction must be furnished:", "At the time the documents are signed or become available", ["Within ten days of closing", "Only on request"], "82.71 subd. 4"),
    ("mn/conduct", "Negotiations", 3, "If the listing broker acts as the transaction closing agent, at closing the broker must deliver:", "A detailed closing statement to the seller and a statement of the disposition of the buyer's money to the buyer", ["Only the seller's statement", "Only the HUD-1"], "82.71 subd. 5"),
    ("mn/conduct", "Records", 1, "A Minnesota broker must retain transaction records for:", "Six years", ["Three years", "Five years", "Ten years"], "82.72 subd. 3"),
