    ("mn/conduct", "Civil actions", 3, "A suit for compensation for licensed acts requires alleging and proving:", "That the person was duly licensed when the cause of action arose", ["That the client benefited", "That the fee was reasonable"], "82.85 subd. 1"),

    # trust
    ("mn/trust", "Who holds", 1, "Unless the parties agree otherwise in writing, Minnesota earnest money is deposited with:", "The listing broker", ["The buyer's broker", "The closing agent", "The seller's attorney"], "82.75 subd. 5(b)"),
    ("mn/trust", "Timing", 1, "If the purchase agreement is silent, earnest money must be deposited within:", "Three business days of receipt or final acceptance, whichever is later", ["Three business days of receipt", "The next business day", "Seven business days of acceptance"], "82.75 subd. 5(c)"),
    ("mn/trust", "Timing", 2, "If the offer is rejected, earnest money must be returned:", "Not later than the next business day after rejection", ["Within three business days", "Within ten business days", "On the buyer's written demand"], "82.75 subd. 5(c)"),
    ("mn/trust", "Disbursement", 2, "Trust funds may be disbursed only on:", "A closing, a written agreement of the parties, a 559.217 affidavit, or a court order", ["The broker's good-faith determination", "A 30-day notice to both parties"], "82.75 subd. 5(d)"),
    ("mn/trust", "Disbursement", 2, "If the agreements are silent, disbursement must be made within:", "Ten business days following consummation or termination", ["Three business days", "Thirty days", "Immediately"], "82.75 subd. 5(d)"),
    ("mn/trust", "Commingling", 2, "A Minnesota broker may keep personal funds in the trust account:", "Only as a specifically identified sum to pay service charges or meet the minimum balance", ["Up to $1,000 for any purpose", "Never, for any reason"], "82.75 subd. 4"),
    ("mn/trust", "Commingling", 2, "Commingling trust funds with the licensee's own money is:", "A fraudulent, deceptive or dishonest practice", ["A bookkeeping error", "Permitted if corrected monthly"], "82.81 subd. 12(a)(12)"),
    ("mn/trust", "Nondepositable", 3, "A buyer offers a stock certificate as earnest money. The broker must:", "Deposit it immediately with an authorised escrow agent under a written agreement and issue the buyer a receipt", ["Deposit it in the trust account", "Hold it in the office safe"], "82.75 subd. 3"),
    ("mn/trust", "Interest", 2, "Interest on a broker's pooled trust account is paid to:", "The Minnesota Housing Finance Agency, for the housing trust fund, unless the parties agree otherwise in writing", ["The broker", "The buyer", "The state general fund"], "82.75 subd. 8(a)"),
    ("mn/trust", "Interest", 3, "That trust account interest must be paid at least:", "Quarterly", ["Monthly", "Annually", "At each closing"], "82.75 subd. 8(b)(1)"),
    ("mn/trust", "Interest", 3, "Trust funds may be placed in an interest-bearing account or certificate of deposit if:", "Buyer and seller consent in writing to the account and to the disposition of the interest", ["The broker discloses it at closing", "The Commissioner approves"], "82.75 subd. 9"),
    ("mn/trust", "Notice", 2, "A broker may not close an existing trust account without giving the Commissioner:", "Ten days' written notice", ["Thirty days' written notice", "Notice afterward", "Any notice"], "82.75 subd. 6"),
    ("mn/trust", "Notice", 3, "Trust account numbers must be provided to the Commissioner:", "At the time of application for the licence, with any change reported immediately", ["At the first renewal", "Only when audited"], "82.75 subd. 6"),
    ("mn/trust", "Records", 2, "A broker's trust records must show:", "A monthly balance of the trust account", ["A quarterly bank reconciliation only", "An annual audit opinion"], "82.75 subd. 11(a)(6)"),
    ("mn/trust", "Records", 3, "A broker must keep, for each beneficiary or transaction:", "A separate record identifying the transaction and the parties with each deposit and disbursement", ["A single combined ledger", "Only the closing statement"], "82.75 subd. 11(b)"),
    ("mn/trust", "Principal", 3, "A licensee acting as principal who receives funds that would be trust funds must:", "Place them in a trust account unless a written agreement signed by all parties specifies otherwise", ["Treat them as personal funds", "Deposit them with the county"], "82.75 subd. 10"),
    ("mn/trust", "Deposits", 3, "Minnesota residential security deposits bear interest at:", "One percent simple noncompounded per annum", ["Three percent compounded", "The bank's posted rate", "No interest"], "504B.178 subd. 2"),
    ("mn/trust", "Deposits", 3, "Security deposit interest amounts under which figure are excluded?", "$1", ["$5", "$10", "$25"], "504B.178 subd. 2"),
    ("mn/trust", "Trust account", 2, "Failing to maintain a trust account at all times is:", "A fraudulent, deceptive or dishonest practice", ["Permitted while holding no funds", "A reporting violation only"], "82.81 subd. 12(a)(15)"),

